/**
 * Prediction types for the pro subscriber predictions feature.
 * These types define the structure of predictions generated by the system.
 */

/**
 * The type of prediction being made.
 * Currently supports 'result' for match outcome predictions.
 * Extensible for future prediction types like 'over_under', 'btts', etc.
 */
export type PredictionType = 'result';

/**
 * Confidence level based on probability percentage.
 * - very_high: >= 90% probability
 * - high: >= 70% and < 90% probability
 * - medium: >= 50% and < 70% probability
 * - low: < 50% probability
 */
export type ConfidenceLevel = 'very high' | 'high' | 'medium' | 'low';

/**
 * The predicted match result (including draw).
 */
export type MatchResult = 'home' | 'away' | 'draw';

/**
 * Outcome probabilities for all three possible results.
 */
export type OutcomeProbabilities = {
  /** Win probability for home team (0-100) */
  homeWin: number;
  /** Draw probability (0-100) */
  draw: number;
  /** Win probability for away team (0-100) */
  awayWin: number;
};

/**
 * Factor contribution to the prediction.
 */
export type PredictionFactor = {
  /** Name of the factor (e.g., "Bookmaker Odds", "Recent Form") */
  name: string;
  /** Description of the factor's influence */
  description: string;
  /** Impact direction: positive favors home, negative favors away */
  impact: 'home' | 'away' | 'neutral';
  /** Weight of this factor (0-1) */
  weight: number;
};

/**
 * Favored team information for the prediction.
 */
export type FavoredTeam = {
  id: number;
  name: string;
};

/**
 * A single prediction for a fixture (enhanced with backward compatibility).
 */
export type Prediction = {
  /** The type of prediction */
  type: PredictionType;

  // --- Old fields (kept for backward compatibility) ---
  /** The predicted result (home, away, or draw) */
  result: MatchResult;
  /** Probability as a percentage (0-100) */
  probability: number;
  /** Confidence level based on probability threshold */
  confidence: ConfidenceLevel;

  // --- New fields ---
  /** Probabilities for all three outcomes */
  probabilities: OutcomeProbabilities;
  /** The predicted outcome: 'home', 'draw', or 'away' */
  predictedOutcome: MatchResult;
  /** The favored team (null for draw prediction) */
  favoredTeam: FavoredTeam | null;
  /** Key factors that influenced this prediction (top 3) */
  keyFactors: PredictionFactor[];
  /** Human-readable summary for UI display */
  summary: string;
};

/**
 * Team information included in predictions.
 */
export type PredictionTeam = {
  id: number;
  name: string;
  logo: string | null;
};

/**
 * League information included in predictions.
 */
export type PredictionLeague = {
  id: number;
  name: string;
  country: string;
};

/**
 * A complete prediction for a single fixture.
 */
export type FixturePrediction = {
  /** The fixture ID from Sportmonks */
  fixtureId: number;
  /** Home team details */
  homeTeam: PredictionTeam;
  /** Away team details */
  awayTeam: PredictionTeam;
  /** Match start time (ISO string) */
  startingAt: string;
  /** League details */
  league: PredictionLeague;
  /** Array of predictions for this fixture */
  predictions: Prediction[];
  /** When this prediction was generated (ISO string) */
  generatedAt: string;
};

/**
 * The response structure for today's predictions endpoint.
 */
export type TodayPredictionsResponse = {
  /** The date these predictions are for (YYYY-MM-DD) */
  date: string;
  /** Array of fixture predictions */
  predictions: FixturePrediction[];
  /** Total number of fixtures analyzed */
  totalFixturesAnalyzed: number;
  /** When these predictions were generated (ISO string) */
  generatedAt: string;
};

/**
 * Internal type for probability calculation results.
 */
export type ProbabilityCalculation = {
  homeProbability: number;
  awayProbability: number;
  drawProbability: number;
  factors: {
    bookmakerOdds: { home: number; away: number; weight: number } | null;
    recentForm: { home: number; away: number; weight: number } | null;
    h2hHistory: { home: number; away: number; weight: number } | null;
    injuries: { home: number; away: number; weight: number } | null;
    newsSentiment: { home: number; away: number; weight: number } | null;
    homeAdvantage: { home: number; away: number; weight: number } | null;
  };
};

/**
 * Redis cache key builder for predictions.
 */
export const PREDICTIONS_CACHE_KEY_PREFIX = 'predictions:today:';

/**
 * Build the Redis cache key for a specific date.
 */
export function buildPredictionsCacheKey(date: string): string {
  return `${PREDICTIONS_CACHE_KEY_PREFIX}${date}`;
}

/**
 * TTL for predictions cache in seconds (25 hours).
 */
export const PREDICTIONS_CACHE_TTL_SECONDS = 25 * 60 * 60;

/**
 * Minimum probability threshold for including a prediction (90%).
 */
export const MIN_PREDICTION_PROBABILITY = 90;

/**
 * Threshold for "very_high" confidence level (90%).
 */
export const VERY_HIGH_CONFIDENCE_THRESHOLD = 90;

/**
 * Threshold for "high" confidence level (70%).
 */
export const HIGH_CONFIDENCE_THRESHOLD = 70;

/**
 * Threshold for "medium" confidence level (50%).
 */
export const MEDIUM_CONFIDENCE_THRESHOLD = 50;
